// Preserve the user-selected corporate artwork byte for byte; UI CSS shows its English row.
import { readFileSync, writeFileSync, copyFileSync } from 'node:fs';
const source = new URL('../assets/brand/empyrean.png', import.meta.url);
const data = readFileSync(source);
writeFileSync(new URL('../src/client/empyrean-logo.ts', import.meta.url),
  '// Generated by scripts/make-brand-assets.mjs; provenance: assets/brand/README.md.\n'
  + `export const EMPYREAN_LOGO_URL = ${JSON.stringify(`data:image/png;base64,${data.toString('base64')}`)};\n`);
copyFileSync(source, new URL('../../desktop/assets/empyrean.png', import.meta.url));
for (const file of ['Urbanist.woff2', 'Urbanist-OFL.txt']) {
  copyFileSync(new URL(`../assets/fonts/${file}`, import.meta.url), new URL(`../../desktop/assets/${file}`, import.meta.url));
}
console.log(`Empyrean corporate asset: ${data.length} bytes, unchanged in client and desktop`);
